import unicodedata


def slugify(s):
    s = s.lower()
    # Transliterate: decompose Unicode and strip combining marks
    s = unicodedata.normalize('NFD', s)
    s = ''.join(c for c in s if not unicodedata.combining(c))
    # Replace non-alphanumeric chars with '-'
    out = []
    for ch in s:
        if ch.isalnum():
            out.append(ch)
        else:
            out.append('-')
    # Collapse consecutive hyphens into one
    result = []
    for ch in out:
        if ch == '-' and result and result[-1] == '-':
            continue
        result.append(ch)
    # Strip leading/trailing hyphens
    return ''.join(result).strip('-')

